WITH member_income AS (SELECT m.member_id, m.first_name, m.last_name, i.amount, i.source, i.date_received FROM member m INNER JOIN income i ON m.member_id = i.link_to_member) SELECT member_id, SUM(amount) as total_income, COUNT(DISTINCT source) as source_count, STRING_AGG(DISTINCT source, ', ') as sources FROM member_income GROUP BY member_id HAVING SUM(amount) > 0 ORDER BY total_income DESC LIMIT 50;
